}
EOF
cat > UITests/UITests.swift <<'EOF'
import XCTest

final class UITests: XCTestCase {
    func testInspect() {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        app.activate()
        sleep(2)
        print("ELEMENT_TREE_BEGIN\n\(app.debugDescription)\nELEMENT_TREE_END")
        let room = app.staticTexts["Team Standup"]
        XCTAssertTrue(room.waitForExistence(timeout: 10), "Team Standup not found")
        room.tap()
        sleep(2)
        print("ROOM_TREE_BEGIN\n\(app.debugDescription)\nROOM_TREE_END")
    }
}
EOF
